293	
294	        mvc.perform(put("/api/v1/plans/{key}/occupancies", scheduleKey)
295	                        .contentType(MediaType.APPLICATION_JSON)
296	                        .content(updateBody(key("REQ"), 1,
297	                                occ("G1", key("SEC"), iso(8), iso(9)))))
298	                .andExpect(status().isOk());
299	        mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
300	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(publishKey)))
301	                .andExpect(status().isOk());
302	    }
303	
304	    @Test
305	    void publishRejectsCrossPlanSectionConflictButAllowsAdjacent() throws Exception {
306	        String section = key("SEC");
307	        String first = key("SCH");
308	        createPlan(first, occ("G1", section, iso(8), iso(9)));
309	        publishPlan(first, key("REQ"));
310	
311	        // 重叠 → 422，返回冲突区段与计划
312	        String overlapping = key("SCH");
313	        createPlan(overlapping, occ("G2", section, iso(8), iso(9)));
314	        MvcResult conflict = mvc.perform(post("/api/v1/plans/{key}/publish", overlapping)
315	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(key("REQ"))))
