112	            assertThat(items.get(2).get("scheduleKey").asText()).isEqualTo(planC);
113	            assertThat(items.get(0).get("status").asText()).isEqualTo("CANCELLED");
114	            assertThat(items.get(1).get("status").asText()).isEqualTo("CANCELLED");
115	            assertThat(items.get(2).get("status").asText()).isEqualTo("PUBLISHED");
116	        }
