COMMENT ON COLUMN idempotency_record.id IS '主键';
COMMENT ON COLUMN idempotency_record.op_type IS '操作类型：CREATE / UPDATE / CONSIST / PUBLISH / CANCEL / RESCHEDULE / BATCH_RESCHEDULE / RULES / SECTION';
