        ValidationOutcome outcome = validateForPublish(plan.scheduleKey(), plan.opDate(),
                occupancies, consist, hctx, List.of(plan.id()));
        List<Map<String, Object>> conflicts = union(outcome.slotConflicts(),
                outcome.hazardConflicts());
