package com.example.starter.plan.service;

import com.example.starter.plan.model.HazardRule;
import com.example.starter.plan.web.dto.HazardRuleRequest;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * 危险品隔离纯逻辑校验（无 Spring/DB 依赖，可独立单元测试）。
 *
 * <p>三类检查：
 * <ul>
 *   <li>编组位置重复（CONSIST_POSITION_DUPLICATE）；</li>
 *   <li>互斥类别间隔：同编组内两类危险品车厢的位置距离 |pA-pB|（单位：节车厢）
 *       必须不小于规则要求（HAZARD_SEPARATION，输出实际/要求/差额）；</li>
 *   <li>限制区段授权：完整区段路径上已配置开放清单的区段，编组内每个危险品类别
 *       必须在清单内（HAZARD_UNAUTHORIZED）。</li>
 * </ul>
 * 规则集/区段配置自身校验产出 RULE_*/SECTION_* 冲突；所有输出列表排序稳定。
 */
public final class HazardValidation {

    private HazardValidation() {
    }

    /**
     * 编组车厢（位置 + 可空危险品类别，null 表示普通车厢）。
     */
    public record Car(int position, String hazardClass) {
    }

    /**
     * 规则集规范化结果。
     *
     * @param rules     规范化后的规则（类别对字母序、按类别对排序、完全相同的重复对去重）
     * @param conflicts 配置冲突（同类别对要求不一致等）；非空时配置不得落库
     */
    public record RulesNormalization(List<HazardRule> rules, List<Map<String, Object>> conflicts) {
    }

    /**
     * 规范化规则集：类别对按字母序排列；完全相同的规则去重；
     * 同类别对要求不一致报 RULE_PAIR_CONFLICT；同类别互斥报 RULE_SAME_CLASS。
     */
    public static RulesNormalization normalizeRules(List<HazardRuleRequest> raw) {
        List<Map<String, Object>> conflicts = new ArrayList<>();
        Map<String, HazardRule> byPair = new TreeMap<>();
        for (int i = 0; i < raw.size(); i++) {
            HazardRuleRequest r = raw.get(i);
            int index = i;
            if (r.classA().equals(r.classB())) {
                conflicts.add(detail("RULE_SAME_CLASS", d -> {
                    d.put("index", index);
                    d.put("classA", r.classA());
                    d.put("classB", r.classB());
                    d.put("reason", "互斥类别对不能是同一类别");
                }));
                continue;
            }
            HazardRule rule = HazardRule.ordered(r.classA(), r.classB(), r.minSeparationCars());
            HazardRule existing = byPair.get(rule.classA() + "\u0001" + rule.classB());
            if (existing == null) {
                byPair.put(rule.classA() + "\u0001" + rule.classB(), rule);
            } else if (existing.minSeparationCars() != rule.minSeparationCars()) {
                int requiredIndex = index;
                conflicts.add(detail("RULE_PAIR_CONFLICT", d -> {
                    d.put("classA", rule.classA());
                    d.put("classB", rule.classB());
                    d.put("requiredCars", existing.minSeparationCars());
                    d.put("conflictingRequiredCars", rule.minSeparationCars());
                    d.put("index", requiredIndex);
                    d.put("reason", "同一类别对配置了不同的最小间隔车厢数");
                }));
            }
            // 完全相同的重复规则视为去重，不报冲突
        }
        return new RulesNormalization(List.copyOf(byPair.values()), conflicts);
    }

    /**
     * 校验开放清单自身：类别重复报 SECTION_CLASS_DUPLICATE。
     * 返回去重后按字母序排列的清单（调用方仅在冲突为空时使用）。
     */
    public static List<String> normalizeAllowedClasses(List<String> raw,
                                                       List<Map<String, Object>> conflicts) {
        Set<String> seen = new LinkedHashSet<>();
        Set<String> duplicated = new LinkedHashSet<>();
        for (String c : raw) {
            if (!seen.add(c)) {
                duplicated.add(c);
            }
        }
        for (String c : duplicated) {
            conflicts.add(detail("SECTION_CLASS_DUPLICATE", d -> {
                d.put("hazardClass", c);
                d.put("reason", "开放清单中危险品类别重复");
            }));
        }
        return seen.stream().sorted().toList();
    }

    /**
     * 编组位置重复检查，重复位置列出全部登记序号对（按 (position, firstIndex, otherIndex) 排序）。
     */
    public static List<Map<String, Object>> findDuplicatePositions(List<Car> cars) {
        Map<Integer, List<Integer>> indexesByPosition = new TreeMap<>();
        for (int i = 0; i < cars.size(); i++) {
            indexesByPosition.computeIfAbsent(cars.get(i).position(), k -> new ArrayList<>()).add(i);
        }
        List<Map<String, Object>> conflicts = new ArrayList<>();
        for (Map.Entry<Integer, List<Integer>> entry : indexesByPosition.entrySet()) {
            List<Integer> indexes = entry.getValue();
            if (indexes.size() < 2) {
                continue;
            }
            for (int a = 0; a < indexes.size(); a++) {
                for (int b = a + 1; b < indexes.size(); b++) {
                    int firstIndex = indexes.get(a);
                    int otherIndex = indexes.get(b);
                    conflicts.add(detail("CONSIST_POSITION_DUPLICATE", d -> {
                        d.put("position", entry.getKey());
                        d.put("firstIndex", firstIndex);
                        d.put("otherIndex", otherIndex);
                    }));
                }
            }
        }
        return conflicts;
    }

    /**
     * 互斥类别间隔检查（在完整编组上）。对每条规则扫描两类车厢的全部跨类位置对，
     * 位置距离（|pA-pB|，节）小于要求时输出实际值、要求值与差额，按稳定顺序排列。
     */
    public static List<Map<String, Object>> findSeparationConflicts(List<HazardRule> rules,
                                                                    List<Car> cars) {
        List<Car> sorted = cars.stream().sorted(Comparator.comparingInt(Car::position)).toList();
        List<Map<String, Object>> conflicts = new ArrayList<>();
        for (HazardRule rule : rules) {
            List<Car> classACars = sorted.stream()
                    .filter(c -> rule.classA().equals(c.hazardClass())).toList();
            List<Car> classBCars = sorted.stream()
                    .filter(c -> rule.classB().equals(c.hazardClass())).toList();
            for (Car a : classACars) {
                for (Car b : classBCars) {
                    int actual = Math.abs(a.position() - b.position());
                    if (actual < rule.minSeparationCars()) {
                        int actualCars = actual;
                        conflicts.add(detail("HAZARD_SEPARATION", d -> {
                            d.put("classA", rule.classA());
                            d.put("classB", rule.classB());
                            d.put("positionA", a.position());
                            d.put("positionB", b.position());
                            d.put("actualCars", actualCars);
                            d.put("requiredCars", rule.minSeparationCars());
                            d.put("deficitCars", rule.minSeparationCars() - actualCars);
                        }));
                    }
                }
            }
        }
        return conflicts;
    }

    /**
     * 限制区段类别授权检查（在完整区段路径与完整编组上）。
     *
     * @param pathSections                 计划完整区段路径（去重），仅决定检查顺序
     * @param cars                         完整编组
     * @param allowedByConfiguredSection   已配置（受限）区段的开放清单；未在此 map 中的区段不限制
     */
    public static List<Map<String, Object>> findUnauthorizedClasses(
            List<String> pathSections, List<Car> cars,
            Map<String, List<String>> allowedByConfiguredSection) {
        List<Car> hazardCars = cars.stream()
                .filter(c -> c.hazardClass() != null)
                .sorted(Comparator.comparingInt(Car::position))
                .toList();
        List<Map<String, Object>> conflicts = new ArrayList<>();
        for (String sectionId : pathSections.stream().sorted().toList()) {
            List<String> allowed = allowedByConfiguredSection.get(sectionId);
            if (allowed == null) {
                continue;
            }
            for (Car car : hazardCars) {
                if (!allowed.contains(car.hazardClass())) {
                    conflicts.add(detail("HAZARD_UNAUTHORIZED", d -> {
                        d.put("sectionId", sectionId);
                        d.put("position", car.position());
                        d.put("hazardClass", car.hazardClass());
                        d.put("allowedClasses", allowed);
                    }));
                }
            }
        }
        return conflicts;
    }

    private static Map<String, Object> detail(String type,
                                              java.util.function.Consumer<Map<String, Object>> filler) {
        Map<String, Object> map = new LinkedHashMap<>();
        map.put("type", type);
        filler.accept(map);
        return map;
    }
}

package com.example.starter.plan.web;

import com.example.starter.plan.service.HazardConfigService;
import com.example.starter.plan.service.PlanService;
import com.example.starter.plan.web.dto.BatchRescheduleRequest;
import com.example.starter.plan.web.dto.BatchRescheduleResponse;
import com.example.starter.plan.web.dto.CreatePlanRequest;
import com.example.starter.plan.web.dto.HazardRuleSetView;
import com.example.starter.plan.web.dto.PlanActionRequest;
import com.example.starter.plan.web.dto.PlanDiagnosticsView;
import com.example.starter.plan.web.dto.PlanResponse;
import com.example.starter.plan.web.dto.PublishSnapshotView;
import com.example.starter.plan.web.dto.PublishedSlotView;
import com.example.starter.plan.web.dto.ReplaceHazardRulesRequest;
import com.example.starter.plan.web.dto.RescheduleChainResponse;
import com.example.starter.plan.web.dto.RescheduleRequest;
import com.example.starter.plan.web.dto.RescheduleResponse;
import com.example.starter.plan.web.dto.SectionRestrictionView;
import com.example.starter.plan.web.dto.UpdateConsistRequest;
import com.example.starter.plan.web.dto.UpdateOccupanciesRequest;
import com.example.starter.plan.web.dto.UpdateSectionRestrictionRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDate;
import java.util.List;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.Put;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/**
 * 铁路走廊日计划 API：草稿创建/占用与危险品编组整体替换、发布（危险品隔离校验 + 快照）、
 * 取消、单个/批量原子改签、计划明细/改签链/发布快照/诊断/已发布时隙查询，
 * 以及危险品互斥规则集与限制区段开放清单的版本化配置。
 */
@Validated
@RestController
@RequestMapping("/api/v1")
public class PlanController {

    private final PlanService service;
    private final HazardConfigService hazardConfigService;

    public PlanController(PlanService service, HazardConfigService hazardConfigService) {
        this.service = service;
        this.hazardConfigService = hazardConfigService;
    }

    /**
     * 创建草稿计划。
     */
    @PostMapping("/plans")
    @ResponseStatus(HttpStatus.CREATED)
    public PlanResponse create(@Valid @RequestBody CreatePlanRequest request) {
        return service.createDraft(request);
    }

    /**
     * 整体替换草稿占用清单（expectedVersion 乐观校验，成功版本加一）。
     */
    @PutMapping("/plans/{scheduleKey}/occupancies")
    public PlanResponse replaceOccupancies(@PathVariable String scheduleKey,
                                           @Valid @RequestBody UpdateOccupanciesRequest request) {
        return service.replaceOccupancies(scheduleKey, request);
    }

    /**
     * 整体替换草稿危险品编组（expectedVersion 乐观校验，成功版本加一；位置重复 422）。
     */
    @PutMapping("/plans/{scheduleKey}/consist")
    public PlanResponse replaceConsist(@PathVariable String scheduleKey,
                                       @Valid @RequestBody UpdateConsistRequest request) {
        return service.replaceConsist(scheduleKey, request);
    }

    /**
     * 发布计划：在完整编组与完整区段路径上原子校验时隙冲突与危险品隔离，并固化发布快照。
     */
    @PostMapping("/plans/{scheduleKey}/publish")
    public PlanResponse publish(@PathVariable String scheduleKey,
                                @Valid @RequestBody PlanActionRequest request) {
        return service.publish(scheduleKey, request.requestKey(), request.operator());
    }

    /**
     * 取消已发布计划，时隙立即释放，历史与发布快照保留。
     */
    @PostMapping("/plans/{scheduleKey}/cancel")
    public PlanResponse cancel(@PathVariable String scheduleKey,
                               @Valid @RequestBody PlanActionRequest request) {
        return service.cancel(scheduleKey, request.requestKey());
    }

    /**
     * 原子改签：同一事务取消旧计划并发布新草稿，追加不可变前后继关联与发布快照；
     * 任一校验失败整体回滚。
     */
    @PostMapping("/plans/{scheduleKey}/reschedule")
    public RescheduleResponse reschedule(@PathVariable String scheduleKey,
                                         @Valid @RequestBody RescheduleRequest request) {
        return service.reschedule(scheduleKey, request);
    }

    /**
     * 批量原子改签：所有改签项先在完整后态上统一校验，全部合法才在一个事务内提交，
     * 含任一非法计划时整次不改变时隙或编组。
     */
    @PostMapping("/batch-reschedules")
    public BatchRescheduleResponse batchReschedule(@Valid @RequestBody BatchRescheduleRequest request) {
        return service.batchReschedule(request);
    }

    /**
     * 查询包含指定计划在内的完整有序改签链。
     */
    @GetMapping("/plans/{scheduleKey}/reschedule-chain")
    public RescheduleChainResponse getRescheduleChain(@PathVariable String scheduleKey) {
        return service.getRescheduleChain(scheduleKey);
    }

    /**
     * 查询计划发布快照（固化编组、类别、区段限制版本与校验结论）。
     */
    @GetMapping("/plans/{scheduleKey}/publish-snapshot")
    public PublishSnapshotView getPublishSnapshot(@PathVariable String scheduleKey) {
        return service.getSnapshot(scheduleKey);
    }

    /**
     * 只读诊断：以当前危险品配置对计划当前编组与区段路径执行与发布相同的校验。
     */
    @GetMapping("/plans/{scheduleKey}/diagnostics")
    public PlanDiagnosticsView diagnose(@PathVariable String scheduleKey) {
        return service.diagnose(scheduleKey);
    }

    /**
     * 计划明细（含历史占用与编组）。
     */
    @GetMapping("/plans/{scheduleKey}")
    public PlanResponse getPlan(@PathVariable String scheduleKey) {
        return service.getPlan(scheduleKey);
    }

    /**
     * 按运营日期与区段查询当前已发布时隙。
     */
    @GetMapping("/published-slots")
    public List<PublishedSlotView> getPublishedSlots(
            @RequestParam @NotNull @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date,
            @RequestParam @NotBlank String sectionId) {
        return service.getPublishedSlots(date, sectionId);
    }

    /**
     * 整体替换危险品互斥规则集（expectedVersion 乐观校验，追加新版本；配置非法 422 不落库）。
     */
    @PutMapping("/hazard-rules")
    public HazardRuleSetView replaceHazardRules(@Valid @RequestBody ReplaceHazardRulesRequest request) {
        return hazardConfigService.replaceRules(request);
    }

    /**
     * 查询当前危险品互斥规则集版本。
     */
    @GetMapping("/hazard-rules")
    public HazardRuleSetView getHazardRules() {
        return hazardConfigService.getCurrentRules();
    }

    /**
     * 整体替换限制区段危险品开放清单（expectedVersion 乐观校验，追加新版本）。
     */
    @PutMapping("/sections/{sectionId}/restriction")
    public SectionRestrictionView replaceSectionRestriction(@PathVariable String sectionId,
                                                            @Valid
                                                            @RequestBody UpdateSectionRestrictionRequest request) {
        return hazardConfigService.replaceSectionRestriction(sectionId, request);
    }

    /**
     * 查询限制区段当前开放清单版本（未配置返回 version=0、allowedClasses=null）。
     */
    @GetMapping("/sections/{sectionId}/restriction")
    public SectionRestrictionView getSectionRestriction(@PathVariable String sectionId) {
        return hazardConfigService.getCurrentSection(sectionId);
    }
}

-- 测试库（H2 内存库，MODE=MySQL 兼容模式）结构，与主 schema.sql 完全一致。
-- 所有时刻字段均为 UTC 毫秒时间戳；运营日期按 Asia/Shanghai 解释。

CREATE TABLE IF NOT EXISTS rail_day_plan (
    id BIGINT NOT NULL AUTO_INCREMENT,
    schedule_key VARCHAR(64) NOT NULL,
    op_date DATE NOT NULL,
    version INT NOT NULL,
    status VARCHAR(16) NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_day_plan_schedule_key UNIQUE (schedule_key)
);
COMMENT ON TABLE rail_day_plan IS '铁路走廊日计划主表';
COMMENT ON COLUMN rail_day_plan.id IS '主键';
COMMENT ON COLUMN rail_day_plan.schedule_key IS '计划业务键，全局唯一，取消后仍保留历史';
COMMENT ON COLUMN rail_day_plan.op_date IS '运营日期（Asia/Shanghai 日历日）';
COMMENT ON COLUMN rail_day_plan.version IS '计划版本，草稿占用/编组整体替换成功一次加一';
COMMENT ON COLUMN rail_day_plan.status IS '计划状态：DRAFT 草稿 / PUBLISHED 已发布 / CANCELLED 已取消';
COMMENT ON COLUMN rail_day_plan.created_at IS '创建时刻，UTC 毫秒';
COMMENT ON COLUMN rail_day_plan.updated_at IS '最近变更时刻，UTC 毫秒';

CREATE TABLE IF NOT EXISTS rail_plan_occupancy (
    id BIGINT NOT NULL,
    plan_id BIGINT NOT NULL,
    seq INT NOT NULL,
    train_no VARCHAR(64) NOT NULL,
    section_id VARCHAR(64) NOT NULL,
    start_utc BIGINT NOT NULL,
    end_utc BIGINT NOT NULL,
    PRIMARY KEY (id)
);
COMMENT ON TABLE rail_plan_occupancy IS '计划区段占用明细，区间左闭右开；取消计划后历史占用保留不删除';
COMMENT ON COLUMN rail_plan_occupancy.id IS '主键';
COMMENT ON COLUMN rail_plan_occupancy.plan_id IS '所属计划 id，关联 rail_day_plan.id';
COMMENT ON COLUMN rail_plan_occupancy.seq IS '占用在计划内的序号，从 0 开始，保持提交顺序';
COMMENT ON COLUMN rail_plan_occupancy.train_no IS '列车编号';
COMMENT ON COLUMN rail_plan_occupancy.section_id IS '区段 ID';
COMMENT ON COLUMN rail_plan_occupancy.start_utc IS '占用开始时刻（含），UTC 毫秒';
COMMENT ON COLUMN rail_plan_occupancy.end_utc IS '占用结束时刻（不含），UTC 毫秒，必须大于 start_utc';
CREATE INDEX IF NOT EXISTS idx_rail_plan_occupancy_plan ON rail_plan_occupancy (plan_id);
CREATE INDEX IF NOT EXISTS idx_rail_plan_occupancy_section ON rail_plan_occupancy (section_id, start_utc, end_utc);

-- 危险品编组：计划内一节车厢；hazard_class 为 NULL 表示普通车厢（null 语义固定，不表示未知）。
CREATE TABLE IF NOT EXISTS rail_plan_consist_car (
    id BIGINT NOT NULL AUTO_INCREMENT,
    plan_id BIGINT NOT NULL,
    position INT NOT NULL,
    hazard_class VARCHAR(32),
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_plan_consist_plan_position UNIQUE (plan_id, position)
);
COMMENT ON TABLE rail_plan_consist_car IS '计划危险品编组车厢明细，整体替换；仅草稿可改，发布后随快照固化';
COMMENT ON COLUMN rail_plan_consist_car.id IS '主键';
COMMENT ON COLUMN rail_plan_consist_car.plan_id IS '所属计划 id，关联 rail_day_plan.id';
COMMENT ON COLUMN rail_plan_consist_car.position IS '车厢编组位置（车厢号，从 1 开始），同一计划内唯一；重复登记判 422';
COMMENT ON COLUMN rail_plan_consist_car.hazard_class IS '危险品类别代码；NULL 表示普通车厢（非危险品），空串不合法';

-- 危险品互斥规则集版本：每次整体替换追加新版本行，发布快照引用当时版本，旧版本不删除不回写。
CREATE TABLE IF NOT EXISTS rail_hazard_rule_version (
    id BIGINT NOT NULL AUTO_INCREMENT,
    version INT NOT NULL,
    rules_json CLOB NOT NULL,
    rules_hash CHAR(64) NOT NULL,
    operator VARCHAR(64) NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_hazard_rule_version UNIQUE (version)
);
COMMENT ON TABLE rail_hazard_rule_version IS '危险品互斥类别规则集版本（类别对 + 最小间隔车厢数），整体替换追加，历史保留';
COMMENT ON COLUMN rail_hazard_rule_version.id IS '主键';
COMMENT ON COLUMN rail_hazard_rule_version.version IS '规则集版本号，从 1 开始递增；无配置时视为版本 0 的空规则集';
COMMENT ON COLUMN rail_hazard_rule_version.rules_json IS '规范化规则集 JSON（类别对字母序、按类别对排序），不含未转义拼接';
COMMENT ON COLUMN rail_hazard_rule_version.rules_hash IS '规则集规范化 JSON 的 SHA-256，发布快照记录该哈希';
COMMENT ON COLUMN rail_hazard_rule_version.operator IS '提交操作者，参与幂等指纹';
COMMENT ON COLUMN rail_hazard_rule_version.created_at IS '版本创建时刻，UTC 毫秒';

-- 限制区段开放清单版本：每个区段独立版本化，仅限制区段需要配置；未配置区段不限制危险品类别。
CREATE TABLE IF NOT EXISTS rail_section_restriction (
    id BIGINT NOT NULL AUTO_INCREMENT,
    section_id VARCHAR(64) NOT NULL,
    version INT NOT NULL,
    allowed_classes_json CLOB NOT NULL,
    operator VARCHAR(64) NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_section_restriction_section_version UNIQUE (section_id, version)
);
COMMENT ON TABLE rail_section_restriction IS '限制区段开放清单版本，整体替换追加；未配置区段视为不限制';
COMMENT ON COLUMN rail_section_restriction.id IS '主键';
COMMENT ON COLUMN rail_section_restriction.section_id IS '区段 ID，关联占用中的 section_id';
COMMENT ON COLUMN rail_section_restriction.version IS '该区段配置版本号，从 1 开始；未配置时视为 0（不限制）';
COMMENT ON COLUMN rail_section_restriction.allowed_classes_json IS '开放危险品类别清单 JSON（规范化、字母序去重）；空数组表示该区段不允许任何危险品';
COMMENT ON COLUMN rail_section_restriction.operator IS '提交操作者，参与幂等指纹';
COMMENT ON COLUMN rail_section_restriction.created_at IS '版本创建时刻，UTC 毫秒';
CREATE INDEX IF NOT EXISTS idx_rail_section_restriction_section ON rail_section_restriction (section_id, version);

-- 发布快照：计划发布成功时固化一次，后续配置变更或取消均不改写；每个计划至多一条。
CREATE TABLE IF NOT EXISTS rail_publish_snapshot (
    id BIGINT NOT NULL AUTO_INCREMENT,
    plan_id BIGINT NOT NULL,
    schedule_key VARCHAR(64) NOT NULL,
    plan_version INT NOT NULL,
    consist_json CLOB NOT NULL,
    rule_version INT NOT NULL,
    rules_hash CHAR(64) NOT NULL,
    path_sections_json CLOB NOT NULL,
    section_restrictions_json CLOB NOT NULL,
    result VARCHAR(16) NOT NULL,
    operator VARCHAR(64) NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_publish_snapshot_plan UNIQUE (plan_id)
);
COMMENT ON TABLE rail_publish_snapshot IS '发布快照，固化编组、危险品类别、区段限制版本与校验结论，追加后不可变';
COMMENT ON COLUMN rail_publish_snapshot.id IS '主键';
COMMENT ON COLUMN rail_publish_snapshot.plan_id IS '发布的计划 id，关联 rail_day_plan.id，全表唯一';
COMMENT ON COLUMN rail_publish_snapshot.schedule_key IS '计划业务键快照';
COMMENT ON COLUMN rail_publish_snapshot.plan_version IS '发布时计划版本';
COMMENT ON COLUMN rail_publish_snapshot.consist_json IS '发布时完整编组 JSON（按车厢位置升序，hazardClass 为 null 表示普通车厢）';
COMMENT ON COLUMN rail_publish_snapshot.rule_version IS '校验时危险品互斥规则集版本（0 表示空规则集）';
COMMENT ON COLUMN rail_publish_snapshot.rules_hash IS '校验时规则集 SHA-256';
COMMENT ON COLUMN rail_publish_snapshot.path_sections_json IS '完整区段路径（占用去重并按 sectionId 排序）JSON';
COMMENT ON COLUMN rail_publish_snapshot.section_restrictions_json IS '路径上已配置限制区段的开放清单快照 JSON（含区段、版本、类别清单），未配置区段不在列表中';
COMMENT ON COLUMN rail_publish_snapshot.result IS '校验结论：PASS 通过（仅校验通过才允许发布并写快照）';
COMMENT ON COLUMN rail_publish_snapshot.operator IS '发布操作者';
COMMENT ON COLUMN rail_publish_snapshot.created_at IS '快照创建时刻，UTC 毫秒';

CREATE TABLE IF NOT EXISTS idempotency_record (
    id BIGINT NOT NULL AUTO_INCREMENT,
    op_type VARCHAR(32) NOT NULL,
    request_key VARCHAR(128) NOT NULL,
    request_hash CHAR(64) NOT NULL,
    response_json CLOB NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_idempotency_op_key UNIQUE (op_type, request_key)
);
COMMENT ON TABLE idempotency_record IS '写操作幂等记录，仅缓存成功结果，失败不缓存可重试';
COMMENT ON COLUMN idempotency_record.id IS '主键';
COMMENT ON COLUMN idempotency_record.op_type IS '操作类型：CREATE / UPDATE / CONSIST / PUBLISH / CANCEL / RESCHEDULE / BATCH_RESCHEDULE / RULES / SECTION';
COMMENT ON COLUMN idempotency_record.request_key IS '客户端幂等键，同一操作类型内唯一';
COMMENT ON COLUMN idempotency_record.request_hash IS '请求参数规范化 JSON 后的 SHA-256，同键不同参判定 409';
COMMENT ON COLUMN idempotency_record.response_json IS '首次成功响应快照（JSON），重放原样返回';
COMMENT ON COLUMN idempotency_record.created_at IS '记录创建时刻，UTC 毫秒';

CREATE TABLE IF NOT EXISTS rail_plan_reschedule_link (
    id BIGINT NOT NULL AUTO_INCREMENT,
    predecessor_plan_id BIGINT NOT NULL,
    successor_plan_id BIGINT NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_reschedule_link_predecessor UNIQUE (predecessor_plan_id),
    CONSTRAINT uk_reschedule_link_successor UNIQUE (successor_plan_id)
);
COMMENT ON TABLE rail_plan_reschedule_link IS '改签前后继关联，追加后不可变；一个计划最多一个直接前驱与一个直接后继';
COMMENT ON COLUMN rail_plan_reschedule_link.id IS '主键';
COMMENT ON COLUMN rail_plan_reschedule_link.predecessor_plan_id IS '直接前驱（被改签取消的旧计划）id，关联 rail_day_plan.id，全表唯一';
COMMENT ON COLUMN rail_plan_reschedule_link.successor_plan_id IS '直接后继（改签发布的新计划）id，关联 rail_day_plan.id，全表唯一';
COMMENT ON COLUMN rail_plan_reschedule_link.created_at IS '关联创建时刻，UTC 毫秒';

CREATE TABLE IF NOT EXISTS publish_lock (
    id INT NOT NULL,
    PRIMARY KEY (id)
);
COMMENT ON TABLE publish_lock IS '发布/改签/危险品配置全局互斥锁，保证并发按事务提交顺序裁决';
COMMENT ON COLUMN publish_lock.id IS '锁行 id，固定为 1，发布、改签与配置写入时 SELECT ... FOR UPDATE 串行化';

